  return {
    absent: false,
    uncached: u.uncachedInputTokens ?? u.inputTokens ?? 0,
    cacheRead: u.cacheReadTokens ?? u.cacheRead ?? 0,
    output: u.outputTokens ?? 0,
  };
}

let latestAcc;

/** 测试与排查：最近一次 enabled apply 的会话累计。 */
